// Decodifica tópico nativo: {prefix}/out/{nodeId}/{sensorId}/{command}/{ack}/{type}
// ou formato JSON M360: msg.payload = {nodeId, sensorId, command, ack, type, payload}
var MQTT_PREFIX = global.get('mqtt_topic_prefix') || 'm360/DF/0000';
var parts = msg.topic.split('/');

// --- Formato nativo MySensors (9+ segmentos) ---
if (parts.length >= 9) {
    var nodeId   = parseInt(parts[4]);
    var sensorId = parseInt(parts[5]);
    var command  = parseInt(parts[6]);
    var ack      = parseInt(parts[7]);
    var type     = parseInt(parts[8]);
    if ([nodeId, sensorId, command, ack, type].some(isNaN)) {
        return null;
    }
    msg.payload = {
        nodeId:    nodeId,
        sensorId:  sensorId,
        command:   command,
        ack:       ack,
        type:      type,
        payload:   typeof msg.payload === 'string' ? msg.payload : String(msg.payload),
        direction: ack === 1 ? 'ack' : 'sensor',
        timestamp: Math.floor(Date.now() / 1000)
    };
    msg.topic = MQTT_PREFIX + '/out';
    return msg;
}

// --- Formato JSON M360 gateway (tópico plano, payload JSON) ---
var m = msg.payload;
if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch(e) { return null; }
}
if (!m || m.nodeId === undefined || m.command === undefined) {
    return null;
}
msg.payload = {
    nodeId:    m.nodeId,
    sensorId:  m.sensorId,
    command:   m.command,
    ack:       m.ack || 0,
    type:      m.type,
    payload:   String(m.payload !== undefined ? m.payload : ''),
    direction: (m.direction === 'ack' || m.ack == 1) ? 'ack' : 'sensor',
    timestamp: Math.floor(Date.now() / 1000)
};
msg.topic = MQTT_PREFIX + '/out';
return msg;

