    }
    options.push({ label: label, value: Number(id) });
});

// Se a lista estiver vazia, coloca fallbacks padrão
if (options.length === 0) {
    options = [
        { label: "Nó 01 (Solo/Estufa)", value: 1 },
        { label: "Nó 04 (Clima/Solar)", value: 4 },
        { label: "Nó 13 (Solo Modbus/ZTS)", value: 13 },
        { label: "Nó 99 (Atuador Central)", value: 99 }
    ];
}

msg.options = options;

// Preserva a seleção atual se houver
var currentSelected = flow.get('ui_selected_node_id');
if (currentSelected !== undefined) {
    msg.payload = currentSelected;
} else {
    delete msg.payload;
}

return msg;

var m = msg.payload;
var isDryBattery = (m.command === 1 && m.sensorId === 255 && m.type === 38);
var isNativeBattery = (m.command === 3 && m.type === 0);
if (m.nodeId == 4 && (isDryBattery || isNativeBattery)) {
    msg.topic = 'Bateria SolarMini';
    msg.payload = parseFloat(m.payload);
    msg.ts = Date.now();
    return msg;
}
return null;

var CUTOFF = 86400000;
var hist = flow.get('hist_bateria') || [];
hist.push({ topic: msg.topic, payload: msg.payload, ts: msg.ts });
var now = Date.now();
hist = hist.filter(function(p) { return (now - p.ts) < CUTOFF; });
flow.set('hist_bateria', hist);
return msg;

var m = msg.payload;
if (m.nodeId === 99 && (m.sensorId === 20 || m.sensorId === 21 || m.sensorId === 22)) {
    var canteiro = '';
    var canteiroKey = '';
    if (m.sensorId === 20) {
        canteiro = 'Canteiro A';
        canteiroKey = 'A';
    } else if (m.sensorId === 21) {
        canteiro = 'Canteiro B';
        canteiroKey = 'B';
    } else if (m.sensorId === 22) {
        canteiro = 'Canteiro N';
        canteiroKey = 'N';
    }
    var flowRate = parseFloat(m.payload) || 0.0;
    var now = Date.now();
    var lastTsKey = 'flow_last_ts_' + canteiroKey;
    var volKey = 'flow_vol_' + canteiroKey;
    var lastTs = flow.get(lastTsKey);
    var volume = flow.get(volKey) || 0.0;
    if (flowRate > 0) {
        if (lastTs && (now - lastTs) < 30000) {
            var dt = (now - lastTs) / 1000;
            var dV = flowRate * dt;
            volume += dV;
            flow.set(volKey, volume);
        }
        flow.set(lastTsKey, now);
    } else {
        if (lastTs && (now - lastTs) < 30000) {
            var dt = (now - lastTs) / 1000;
            var dV = flowRate * dt;
            volume += dV;
            flow.set(volKey, volume);
        }
        flow.set(lastTsKey, null);
    }
    var msgVazao = {
        topic: 'Vazão ' + canteiro,
        payload: flowRate,
        ts: now
    };
    var msgVolume = {
        topic: 'Volume ' + canteiro,
        payload: parseFloat(volume.toFixed(2)),
        ts: now
    };
    return [msgVazao, msgVolume];
}
return null;

